[{"category":"section","location":"numerical_results/scheme3/#Scheme-3","page":"Scheme 3","text":"julia> using WaveAcoustics\n\njulia> cases1 = (\n    (fe = Lagrange{1}, id = example1_manufactured(1.76), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example1_manufactured(2.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example1_manufactured(2.58), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example1_manufactured(3.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example1_manufactured(3.51), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example1_manufactured(4.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example1_manufactured(2.4 ), Nx = 2^9, τ = [2.0^-i for i in 2:5])\n    );\n\njulia> results1 = run_cases(Scheme3(), cases1)\n\njulia> cases2 = (\n    (fe = Lagrange{1}, id = example2_manufactured(1.76), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example2_manufactured(2.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example2_manufactured(2.58), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example2_manufactured(3.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example2_manufactured(3.51), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example2_manufactured(4.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example2_manufactured(2.4 ), Nx = 2^9, τ = [2.0^-i for i in 2:5])\n    );\n\njulia> results2 = run_cases(Scheme3(), cases2)\n\njulia> cases3 = (\n    (fe = Lagrange{1}, id = example3_manufactured(1.76), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example3_manufactured(2.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example3_manufactured(2.58), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example3_manufactured(3.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example3_manufactured(3.51), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example3_manufactured(4.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example3_manufactured(2.4 ), Nx = 2^9, τ = [2.0^-i for i in 2:5])\n    );\n\njulia> results3 = run_cases(Scheme3(), cases3)\n\njulia> versioninfo()","title":"Scheme 3"},{"category":"section","location":"numerical_results/scheme1/#Scheme-1","page":"Scheme 1","text":"julia> using WaveAcoustics\n\njulia> cases1 = (\n    (fe = Lagrange{1}, id = example1_manufactured(1.76), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example1_manufactured(2.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example1_manufactured(2.58), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example1_manufactured(3.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example1_manufactured(3.51), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example1_manufactured(4.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example1_manufactured(2.4 ), Nx = 2^9, τ = [2.0^-i for i in 2:5])\n    );\n\njulia> results1 = run_cases(Scheme1(), cases1)\n\njulia> cases2 = (\n    (fe = Lagrange{1}, id = example2_manufactured(1.76), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example2_manufactured(2.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example2_manufactured(2.58), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example2_manufactured(3.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example2_manufactured(3.51), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example2_manufactured(4.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example2_manufactured(2.4 ), Nx = 2^9, τ = [2.0^-i for i in 2:5])\n    );\n\njulia> results2 = run_cases(Scheme1(), cases2)\n\njulia> cases3 = (\n    (fe = Lagrange{1}, id = example3_manufactured(1.76), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example3_manufactured(2.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example3_manufactured(2.58), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example3_manufactured(3.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example3_manufactured(3.51), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example3_manufactured(4.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example3_manufactured(2.4 ), Nx = 2^9, τ = [2.0^-i for i in 2:5])\n    );\n\njulia> results3 = run_cases(Scheme1(), cases3)\n\njulia> versioninfo()","title":"Scheme 1"},{"category":"section","location":"api/#Index","page":"API","text":"","title":"Index"},{"category":"section","location":"api/#Public-API","page":"API","text":"","title":"Public API"},{"category":"section","location":"api/#Internal-API","page":"API","text":"","title":"Internal API"},{"category":"type","location":"api/#WaveAcoustics.ConvergenceResults","page":"API","text":"ConvergenceResults{T,I}\n\nStores the output of a mesh-refinement convergence study.\n\nFields\n\ninfo  : description of the run\nNx    : number of elements per spatial direction at each refinement level\nh     : element diameter √(Δx²+Δy²) at each level\nτ     : time-step size at each level\nerrors: L∞(L²) error norms; size (n_levels, n_fields)\nrates : convergence rates, computed as log(eᵢ₋₁/eᵢ)/log(δᵢ₋₁/δᵢ), where δ denotes the refinement parameter: δ = h for 2D spatial studies, δ = Δx for 1D spatial studies, and δ = τ for temporal studies; same size as errors\n\n\n\n\n\n","title":"WaveAcoustics.ConvergenceResults"},{"category":"type","location":"api/#WaveAcoustics.L2ErrorCallback","page":"API","text":"L2ErrorCallback{T}\n\nCallback that computes the L²(Ω) error between the numerical and exact solutions at each time step.\n\nFields\n\nv_errors::Vector{T}: L² errors for the wave velocity field (length(tspan))\nd_errors::Vector{T}: L² errors for the wave displacement field\nr_errors::Vector{T}: L² errors for the acoustic velocity\nz_errors::Vector{T}: L² errors for the acoustic displacement\n\n\n\n\n\n","title":"WaveAcoustics.L2ErrorCallback"},{"category":"method","location":"api/#WaveAcoustics.L2ErrorCallback-Union{Tuple{StepRangeLen{T}}, Tuple{T}} where T","page":"API","text":"L2ErrorCallback(tspan)\n\nAllocate an L2ErrorCallback for length(tspan) time steps.\n\n\n\n\n\n","title":"WaveAcoustics.L2ErrorCallback"},{"category":"type","location":"api/#WaveAcoustics.PDEInputData","page":"API","text":"PDEInputData{Tα, Tf, Tdf, Tg, T∂ₛg, \n             Tu₀, T∂ₓu₀, T∂ᵧu₀, \n             Tv₀, T∂ₓv₀, T∂ᵧv₀, \n             Tz₀, Tr₀, \n             Tf₁, Tf₂, \n             Tu, Tv, Tz, Tr}\n\nInput data for a coupled wave-acoustic PDE system on a rectangular domain Omega = x_min x_max times y_min y_max, with acoustic interaction prescribed on the lower boundary Gamma_1 = x_min x_max times y_min, where Gamma = partialOmega and Gamma_0 = Gamma setminus Gamma_1.\n\nMathematical Model\n\nbeginalign*\nbeginaligned\n u^primeprime(xyt) \n- alpha(t)Delta u(xyt) \n+ fbig(u(xyt)big) \n= f_1(xyt)\n5pt\n q_1 z^primeprime(xt)\n+ q_2 z^prime(xt)\n+ q_3 z(xt)\n+ q_4 u^prime(xy_mint)\n= f_2(xt)\n5pt\n -fracpartial upartial y(xy_mint)\n= z^prime(xt)\n- gbig(xu^prime(xy_mint)big)\nquad(xt)inx_minx_maxtimes(0+infty)\n5pt\n u(xyt) = 0quad (xyt)inGamma_0times(0+infty)\nendaligned\nendalign*\n\nwith initial conditions\n\nbeginalign*\nbeginaligned\n u(xy0) = u_0(xy)quad u^prime(xy0)=v_0(xy)quad (xy)inOmega\n\n z(x0) = z_0(x)quad\n  z^prime(x0) = r_0(x) equiv -fracpartial u_0partial y(xy_min) + gbig(xv_0(xy_min)big)quad xinx_miny_max\nendaligned\nendalign*\n\nFields\n\nProblem Identification\n\nname::String: Identifier for the problem instance (e.g., \"example1_manufactured(2.4)\")\n\nDomain Geometry\n\npmin::NTuple{2,Float64}: Bottom-left corner (x_min y_min) of Ω.\npmax::NTuple{2,Float64}: Top-right corner (x_max y_max) of Ω.\n\nPhysical Parameters\n\nq₁::Float64: Acoustic acceleration coefficient\nq₂::Float64: Acoustic velocity coefficient\nq₃::Float64: Acoustic displacement coefficient\nq₄::Float64: Wave-acoustic coupling strength\n\nCoefficient Functions\n\nα::Tα: Time-dependent wave diffusion coefficient α(t)\nf::Tf, df::Tdf: Nonlinear wave term f(s) and derivative f'(s)\ng::Tg, ∂ₛg::T∂ₛg: Nonlinear coupling g(x,s) and s-derivative ∂ₛg(x,s)\n\nWave Initial Conditions (2D functions on Ω)\n\nu₀::Tu₀: Displacement u(x,y,0)\n∂ₓu₀::T∂ₓu₀, ∂ᵧu₀::T∂ᵧu₀: Spatial derivatives of displacement\nv₀::Tv₀: Velocity v(x,y,0) = ∂ₜu(x,y,0)\n∂ₓv₀::T∂ₓv₀, ∂ᵧv₀::T∂ᵧv₀: Spatial derivatives of velocity\n\nAcoustic Initial Conditions (1D functions on Γ₁)\n\nz₀::Tz₀: Acoustic displacement z(x,0)\nr₀::Tr₀: Acoustic velocity r(x,0) = ∂ₜz(x,0)\n\nSource Terms\n\nf₁::Tf₁: Wave source term f₁(x,y,t) on Ω\nf₂::Tf₂: Acoustic source term f₂(x,t) on Γ₁\n\nAnalytical Solutions\n\nFor manufactured solution cases, provide analytical solutions for convergence studies:\n\nu::Tu, v::Tv: Analytical wave solutions u(x,y,t), v(x,y,t)\nz::Tz, r::Tr: Analytical acoustic solutions z(x,t), r(x,t)\n\nFor physical simulations without known solutions, these fields are nothing.\n\n\n\n\n\n","title":"WaveAcoustics.PDEInputData"},{"category":"type","location":"api/#WaveAcoustics.Scheme1","page":"API","text":"Scheme1 <: AbstractODESolver\n\nStandard Crank-Nicolson scheme for the PDE system. See Scheme 1 in the method documentation for the full problem formulation.\n\n\n\n\n\n","title":"WaveAcoustics.Scheme1"},{"category":"type","location":"api/#WaveAcoustics.Scheme2","page":"API","text":"Scheme2 <: AbstractODESolver\n\nModified Crank-Nicolson scheme for the PDE system. See Scheme 2 in the method documentation for the full problem formulation.\n\n\n\n\n\n","title":"WaveAcoustics.Scheme2"},{"category":"type","location":"api/#WaveAcoustics.Scheme3","page":"API","text":"Scheme3 <: AbstractODESolver\n\nLinearized Crank-Nicolson scheme for the PDE system. See Scheme 3 in the method documentation for the full problem formulation.\n\n\n\n\n\n","title":"WaveAcoustics.Scheme3"},{"category":"type","location":"api/#WaveAcoustics.SolutionCallback","page":"API","text":"SolutionCallback{T}\n\nCallback that stores the full FE coefficient history at every time step.\n\nFields\n\ntspan::StepRangeLen{T}: uniform time grid\nv::Vector{Vector{T}}: FE coefficient history; entry n+1 holds the solution at tspan[n+1]\nd::Vector{Vector{T}}: FE coefficient history; entry n+1 holds the solution at tspan[n+1]\nr::Vector{Vector{T}}: FE coefficient history; entry n+1 holds the solution at tspan[n+1]\nz::Vector{Vector{T}}: FE coefficient history; entry n+1 holds the solution at tspan[n+1]\n\n\n\n\n\n","title":"WaveAcoustics.SolutionCallback"},{"category":"method","location":"api/#WaveAcoustics.SolutionCallback-Union{Tuple{StepRangeLen{T}}, Tuple{T}} where T","page":"API","text":"SolutionCallback(tspan)\n\nAllocate a SolutionCallback for length(tspan) time steps. The solution history is grown lazily via push! at each call to apply!.\n\n\n\n\n\n","title":"WaveAcoustics.SolutionCallback"},{"category":"function","location":"api/#WaveAcoustics.example1_manufactured","page":"API","text":"example1_manufactured(a::Float64=4.4) -> PDEInputData\n\nManufactured solution with g(x s) = (1 + e^-x^2)(sin(s) + 2s) and f(s) = arctan(s):\n\nbeginalignat*2\n u(xyt)   = (x^a - x)(y^a - 1)(4 + t^2) \n z(xt)     = sin(pi x) + (1+e^-x^2)\n                  leftfraccosbig(-2t(x^a-x)big)-12(x^a-x)\n                  - 2t^2(x^a-x)right\nendalignat*\n\nwhere the acoustic displacement z(xt) is obtained by integrating\n\nfraczt(xt) = -fracuy(xy_mint) + gleft(xfracut(xy_mint)right)\n\nArguments\n\na::Float64=4.4: Smoothness parameter controlling solution regularity.\n\nReturns\n\nPDEInputData with analytical solution for convergence study.\n\n\n\n\n\n","title":"WaveAcoustics.example1_manufactured"},{"category":"function","location":"api/#WaveAcoustics.example1_zero_source","page":"API","text":"example1_zero_source(a::Float64=4.4) -> PDEInputData\n\nSame configuration as example1_manufactured but with f₁ = f₂ = 0. No analytical solution available.\n\nArguments\n\na::Float64=4.4: Smoothness parameter for initial conditions.\n\nReturns\n\nPDEInputData with analytical solutions set to nothing.\n\n\n\n\n\n","title":"WaveAcoustics.example1_zero_source"},{"category":"function","location":"api/#WaveAcoustics.example2_manufactured","page":"API","text":"example2_manufactured(a::Float64=4.4) -> PDEInputData\n\nManufactured solution with g(x s) = (1 + e^-x^2)(sin(s) + 2s) and f(s) = ss^3:\n\nbeginalignat*2\n u(xyt)   = (x^a - x)(y^a - 1)(4 + t^2) \n z(xt)     = sin(pi x) + (1+e^-x^2)\n                  leftfraccosbig(-2t(x^a-x)big)-12(x^a-x)\n                  - 2t^2(x^a-x)right\nendalignat*\n\nwhere the acoustic displacement z(xt) is obtained by integrating\n\nfraczt(xt) = -fracuy(xy_mint) + gleft(xfracut(xy_mint)right)\n\nArguments\n\na::Float64=4.4: Smoothness parameter controlling solution regularity.\n\nReturns\n\nPDEInputData with analytical solution for convergence study.\n\n\n\n\n\n","title":"WaveAcoustics.example2_manufactured"},{"category":"function","location":"api/#WaveAcoustics.example2_zero_source","page":"API","text":"example2_zero_source(a::Float64=4.4) -> PDEInputData\n\nSame configuration as example2_manufactured but with f₁ = f₂ = 0. No analytical solution available.\n\nArguments\n\na::Float64=4.4: Smoothness parameter for initial conditions.\n\nReturns\n\nPDEInputData with analytical solutions set to nothing.\n\n\n\n\n\n","title":"WaveAcoustics.example2_zero_source"},{"category":"function","location":"api/#WaveAcoustics.example3_manufactured","page":"API","text":"example3_manufactured(a::Float64=4.4) -> PDEInputData\n\nManufactured solution with g(xs) = (1+e^-x^2)s and f(s) = 0:\n\nbeginalignat*2\n u(xyt)   = (x^a - x)(y^a - 1)(4 + t^2) \n z(xt)     = sin(pi x) - (1+e^-x^2)(x^a-x)t^2\nendalignat*\n\nwhere the acoustic displacement z(xt) is obtained by integrating\n\nfraczt(xt) = -fracuy(xy_mint) + gleft(xfracut(xy_mint)right)\n\nArguments\n\na::Float64=4.4: Smoothness parameter controlling solution regularity.\n\nReturns\n\nPDEInputData with analytical solution for convergence study.\n\n\n\n\n\n","title":"WaveAcoustics.example3_manufactured"},{"category":"function","location":"api/#WaveAcoustics.example3_zero_source","page":"API","text":"example3_zero_source(a::Float64=4.4) -> PDEInputData\n\nSame configuration as example3_manufactured but with f₁ = f₂ = 0. No analytical solution available.\n\nArguments\n\na::Float64=4.4: Smoothness parameter for initial conditions.\n\nReturns\n\nPDEInputData with analytical solutions set to nothing.\n\n\n\n\n\n","title":"WaveAcoustics.example3_zero_source"},{"category":"function","location":"api/#WaveAcoustics.run_cases","page":"API","text":"run_cases(solver, cases, t_end=1.0) -> Vector{ConvergenceResults}\n\nRuns a convergence study for each case in cases, writing each ConvergenceResults to a file named convergence_studies_<solver>_<YYYY-MM-DD_HH-MM-SS>.txt as it becomes available, and returns all results as a vector.\n\nArguments\n\nsolver: time integration scheme, e.g. Scheme1()\ncases::Tuple: tuple of NamedTuples, one per convergence study, each with keys:\nfe: finite element basis with only the polynomial degree fixed (e.g. Lagrange{1})\nid: input data container for the PDE system, e.g. example1_manufactured(2.4)\nNx: number of elements per spatial direction; Int (fixed) or Vector{Int} (refined).\nτ : time step; Float64 (fixed) or Vector{Float64} (refined).\nt_end::Float64=1.0 : final simulation time.\nAt least one of Nx/τ must vary; if both are vectors they must have the same length.\n\nReturns\n\nVector{ConvergenceResults}: one entry per case, in the same order as cases. Results are also written incrementally to the output file described above.\n\nExample\n\njulia> using WaveAcoustics\n\njulia> cases = (\n (fe = Lagrange{1}, id = example1_manufactured(1.76), Nx = [2^i for i in 2:5], τ = 2.0^-13),\n (fe = Lagrange{1}, id = example1_manufactured(2.4 ), Nx = [2^i for i in 2:5], τ = 2.0^-13),\n (fe = Lagrange{2}, id = example1_manufactured(2.58), Nx = [2^i for i in 2:5], τ = 2.0^-13),\n (fe = Lagrange{2}, id = example1_manufactured(3.4 ), Nx = [2^i for i in 2:5], τ = 2.0^-13),\n (fe = Lagrange{3}, id = example1_manufactured(3.51), Nx = [2^i for i in 2:5], τ = 2.0^-13),\n (fe = Lagrange{3}, id = example1_manufactured(4.4 ), Nx = [2^i for i in 2:5], τ = 2.0^-13),\n (fe = Lagrange{1}, id = example1_manufactured(2.4 ), Nx = 2^9, τ = [2.0^-i for i in 2:5])\n );\n\njulia> result = run_cases(Scheme1(), cases)\n\n\n\n\n\n","title":"WaveAcoustics.run_cases"},{"category":"method","location":"api/#WaveAcoustics.run_convergence_study-Union{Tuple{FE}, Tuple{Deg}, Tuple{Type{FE}, Vector{Int64}, Vector{Float64}, WaveAcoustics.AbstractODESolver, PDEInputData, Float64}} where {Deg, FE<:(AbstractFEBasis{Deg})}","page":"API","text":"run_convergence_study(fe, Nx, τ, solver, id, t_end) -> ConvergenceResults\n\nRuns one PDE solve per entry in Nx/τ, collects L∞(L²) errors, and returns a ConvergenceResults.\n\nThree refinement modes are supported, selected by which of Nx/τ vary:\n\nSpatial study: Nx varies, τ fixed, e.g. Nx = [2^i for i in 2:5], τ = 2.0^-11\nTemporal study: Nx fixed, τ varies, e.g. Nx = 2^9, τ = [2.0^-i for i in 2:5]\nCoupled study: Nx and τ both vary, e.g. Nx = [2^i for i in 2:5], h = sqrt{2}./Nx, p = 1, τ = h.^((p+1)/2), where p is the basis polynomial degree\n\nArguments\n\nfe: finite element basis with only the polynomial degree fixed (e.g. Lagrange{1})\nNx: number of elements per spatial direction; Int (fixed) or Vector{Int} (refined).\nτ: time step; Float64 (fixed) or Vector{Float64} (refined).\nsolver: time integration scheme, e.g. Scheme1()\nid: input data container for the PDE system, e.g. example1_manufactured(4.4)\nt_end : final simulation time.\n\nAt least one of Nx/τ must vary; if both are vectors they must have the same length.\n\nReturns\n\nConvergenceResults : L∞(L²) errors and convergence rates for v, d, r, z across all refinement levels, along with mesh/time-step values and run metadata.\n\nExample\n\njulia> using WaveAcoustics\n\njulia> result = run_convergence_study(\n           Lagrange{1}, [2, 4, 8, 16], sqrt(2) ./ [2, 4, 8, 16],\n           Scheme1(), example1_manufactured(2.4), 1.0)\n\n\n\n\n\n","title":"WaveAcoustics.run_convergence_study"},{"category":"method","location":"api/#WaveAcoustics.solve_pde-Union{Tuple{FE}, Tuple{Deg}, Tuple{Type{FE}, Tuple{Int64, Int64}, StepRangeLen{Float64}, PDEInputData, WaveAcoustics.AbstractODESolver, WaveAcoustics.AbstractCallback}} where {Deg, FE<:(AbstractFEBasis{Deg})}","page":"API","text":"solve_pde(fe, nel_per_dim, tspan, input_data, solver, callback)\n\nSolve the PDE system, populating callback in-place.\n\nArguments\n\nfe::Type{FE}: finite element basis with only the polynomial degree fixed (e.g. Lagrange{1})\nnel_per_dim::NTuple{2, Int}: number of elements per spatial direction (e.g. (4, 4))\ntspan::StepRangeLen{Float64}: uniform time grid (e.g. 0:0.1:1)\ninput_data::PDEInputData: input data container for the PDE system (e.g. example1_manufactured(2.4)) \nsolver::AbstractODESolver: time integration scheme (e.g. Scheme1())\ncallback::AbstractCallback: callback invoked at each time step (e.g. L2ErrorCallback(tspan))\n\n\n\n\n\n","title":"WaveAcoustics.solve_pde"},{"category":"type","location":"api/#WaveAcoustics.AbstractCallback","page":"API","text":"AbstractCallback\n\nAbstract type for callbacks invoked at each time step via apply!. The signature of apply! is defined per concrete subtype.\n\n\n\n\n\n","title":"WaveAcoustics.AbstractCallback"},{"category":"type","location":"api/#WaveAcoustics.AbstractODESolver","page":"API","text":"AbstractODESolver\n\nAbstract type for time integration schemes used in solve_pde.\n\nConcrete subtypes\n\nScheme1\nScheme2\n\n\n\n\n\n","title":"WaveAcoustics.AbstractODESolver"},{"category":"type","location":"api/#WaveAcoustics.QuadratureSetup","page":"API","text":"QuadratureSetup{T, Npg, Npg², nb, nb², nb⁴}\n\nPrecomputed quadrature data for finite element assembly using Gauss-Legendre quadrature.\n\nType Parameters\n\nT: Floating-point type\nNpg: Number of Gauss-Legendre quadrature points per dimension\nNpg²: Npg^2, total number of 2D quadrature points\nnb: Number of 1D basis functions\nnb²: nb^2, number of 2D basis functions\nnb⁴: nb^4, the number of entries in a nb² × nb² matrix\n\nFields\n\nP::SVector{Npg}: Quadrature points in [-1,1]\nW::SVector{Npg}: Quadrature weights for the interval [-1,1]\nϕP::SVector{Npg, SVector{nb}}: 1D basis functions evaluated at quadrature points; ϕP[i] = ϕ(P[i])\nW_ϕP::SVector{Npg, SVector{nb}}: W_ϕP[i] = W[i] * ϕP[i]\nW_ϕPϕP::SVector{Npg, SMatrix{nb, nb}}: W_ϕPϕP[j][a,b] = W[j] * ϕP[j][a] * ϕP[j][b]\nφP::SMatrix{Npg, Npg, SVector{nb²}}: 2D basis functions at quadrature points; φP[i,j] = φ(P[i], P[j])\nW_φP::SMatrix{Npg, Npg, SVector{nb²}}: W_φP[i,j] = W[i]*W[j] * φP[i,j]\nW_φPφP::SMatrix{Npg, Npg, SMatrix{nb², nb²}}: W_φPφP[i,j][a,b] = W[i]*W[j] * φP[i,j][a] * φP[i,j][b]\nW_∂φ∂ξP::SMatrix{Npg, Npg, SVector{nb²}}: W_∂φ∂ξP[i,j] = W[i]*W[j] * ∂φ/∂ξ(P[i],P[j])\nW_∂φ∂ηP::SMatrix{Npg, Npg, SVector{nb²}}: W_∂φ∂ηP[i,j] = W[i]*W[j] * ∂φ/∂η(P[i],P[j])\nxP::SVector{Npg}: Fixed part of physical x-coordinates; xP = (Δx/2)*(P+1) + xmin\nyP::SVector{Npg}: Fixed part of physical y-coordinates; yP = (Δy/2)*(P+1) + ymin\n\nNotes\n\nFor element at indices (ex, ey), physical quadrature coordinates are:\n\nxeP = @. xP + (ex - 1) * Δx\nyeP = @. yP + (ey - 1) * Δy\n\n\n\n\n\n","title":"WaveAcoustics.QuadratureSetup"},{"category":"method","location":"api/#WaveAcoustics.QuadratureSetup-Union{Tuple{nb²}, Tuple{nb}, Tuple{T}, Tuple{Deg}, Tuple{AbstractFEBasis{Deg, 1}, AbstractFEBasis{Deg, 2}, Tuple{T, T}, Tuple{T, T}}, Tuple{AbstractFEBasis{Deg, 1}, AbstractFEBasis{Deg, 2}, Tuple{T, T}, Tuple{T, T}, Val{nb}}, Tuple{AbstractFEBasis{Deg, 1}, AbstractFEBasis{Deg, 2}, Tuple{T, T}, Tuple{T, T}, Val{nb}, Val{nb²}}} where {Deg, T, nb, nb²}","page":"API","text":"QuadratureSetup(fe1D, fe2D, element_side_lengths, pmin)\n\nConstruct a QuadratureSetup for given 1D and 2D finite element basis.\n\n\n\n\n\n","title":"WaveAcoustics.QuadratureSetup"},{"category":"type","location":"api/#WaveAcoustics.State","page":"API","text":"State{T}\n\nMutable snapshot of the FEM solution at time tₙ.  n and t are updated in-place by the solver loop at each iteration;  solution vectors are fixed references whose contents are overwritten by the time integrator.\n\nFields\n\nn::Int: Current time step index (e.g. 0 for t₀)\nt::T: Current time\nv::Vector{T}: FE coefficients vector of the wave velocity solution Vⁿ(x,y) (size m₁)\nd::Vector{T}: FE coefficients vector of the wave displacement solution Uⁿ(x,y) (size m₁)\nr::Vector{T}: FE coefficients vector of the acoustic velocity solution Rⁿ(x) (size m₂)\nz::Vector{T}: FE coefficients vector of the acoustic displacement solution Zⁿ(x) (size m₂)\n\n\n\n\n\n","title":"WaveAcoustics.State"},{"category":"type","location":"api/#WaveAcoustics.SystemMatrices","page":"API","text":"SystemMatrices{T, I}\n\nGlobal FEM matrices for the PDE system.\n\nFields\n\n_2M_m₁xm₁: mass matrix for the m_1-space.\nM_m₂xm₂: mass matrix for the m_2-space.\nK_m₁xm₁: stiffness matrix for the m_1-space.`.\n\n\n\n\n\n","title":"WaveAcoustics.SystemMatrices"},{"category":"method","location":"api/#WaveAcoustics.SystemMatrices-Union{Tuple{Deg}, Tuple{T}, Tuple{AbstractFEBasis{Deg, 1}, AbstractFEBasis{Deg, 2}, Tuple{T, T}, FEM.DOFMap, FEM.DOFMap}} where {T, Deg}","page":"API","text":"SystemMatrices(fe2D, element_side_lengths, dof_map_m₁, dof_map_m₂, a, τ)\n\nConstruct the global FEM matrices for the PDE system.\n\nArguments\n\nfe1D: FE basis with polynomial degree Deg and spatial dimension 1\nfe2D: FE basis with polynomial degree Deg and spatial dimension 2\nelement_side_lengths: Side lengths of the (axis-aligned) element along each spatial dimension.\ndof_map_m₁: DOF map for the m_1-space (left, right, and top boundaries prescribed).\ndof_map_m₂: DOF map for the m_2-space (all boundaries prescribed).\n\n\n\n\n\n","title":"WaveAcoustics.SystemMatrices"},{"category":"method","location":"api/#Base.show-Tuple{IO, ConvergenceResults}","page":"API","text":"Base.show(io, r::ConvergenceResults)\n\nPrints a compact table of mesh sizes, errors, and convergence rates. Invoked automatically by print, display, and the REPL.\n\n\n\n\n\n","title":"Base.show"},{"category":"method","location":"api/#WaveAcoustics._muladd!-Union{Tuple{I}, Tuple{T}, Tuple{LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, T, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}}} where {T, I}","page":"API","text":"_muladd!(A, cst, B, C)\n\nCompute in-place A = cst * B + C by iterating directly over the nonzero values. Assumes A, B, and C share the same sparsity pattern.\n\n\n\n\n\n","title":"WaveAcoustics._muladd!"},{"category":"method","location":"api/#WaveAcoustics.apply!-Union{Tuple{T}, Tuple{L2ErrorCallback{T}, WaveAcoustics.State{T}, Tuple{Int64, Int64}, Tuple{T, T}, FEM.DOFMap, FEM.DOFMap, WaveAcoustics.QuadratureSetup, PDEInputData}} where T","page":"API","text":"apply!(cb, state, nel_per_dim, element_side_lengths, dof_map_m₁, dof_map_m₂, quad, input_data)\n\nCompute the L²(Ω) error at the current time step.\n\nArguments\n\ncb::L2ErrorCallback{T}: Callback accumulating the error history\nstate::State{T}: Current solver state\nnel_per_dim::NTuple{2, Int}: Number of elements along each spatial dimension\nelement_side_lengths::NTuple{2, T}: Element side lengths (Δx, Δy)\ndof_map_m₁: DOF map for the m₁-space\ndof_map_m₂: DOF map for the m₂-space\nquad: Quadrature setup with fields W, xP, yP, φP, ϕP\ninput_data: PDE input data with the exact solutions\n\n\n\n\n\n","title":"WaveAcoustics.apply!"},{"category":"method","location":"api/#WaveAcoustics.apply!-Union{Tuple{T}, Tuple{SolutionCallback{T}, WaveAcoustics.State{T}, Vararg{Any}}} where T","page":"API","text":"apply!(cb, state, args...)\n\nAppend a copy of the current FE coefficient vector. Extra arguments are accepted and ignored so that all AbstractCallback subtypes share a uniform call signature at the solver level.\n\nArguments\n\ncb::SolutionCallback{T}: Callback accumulating the solution history\nstate::State{T}: Current solver state\n\n\n\n\n\n","title":"WaveAcoustics.apply!"},{"category":"function","location":"api/#WaveAcoustics.build_cache","page":"API","text":"build_cache(solver, matrices)\n\nAllocate and return the solver-specific cache for the time integration. Dispatches on solver to construct the appropriate cache type.\n\nArguments\n\nsolver::AbstractODESolver: time integration scheme (e.g. Scheme1())\nmatrices::SystemMatrices{T, I}: global FEM matrices\n\nExtended help\n\nTo add support for a new solver MySolver, define:\n\nbuild_cache(::MySolver, matrices) = MySolverCache(matrices)\n\n\n\n\n\n","title":"WaveAcoustics.build_cache"},{"category":"method","location":"api/#WaveAcoustics.compute_JH_upper!-Union{Tuple{I}, Tuple{T}, NTuple{4, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}}} where {T, I}","page":"API","text":"compute_JH_upper!(JH_upper, Q, JG, JF)\n\nCompute in-place\n\nJH_upper = Q + ταJG(v̂ⁿ) + (τ²2)JF(d̂ⁿ)\n\nAssumes JH_upper, Q, and JF share the same sparsity pattern, and that JG occupies the leading nnz(JG) entries of that pattern.\n\n\n\n\n\n","title":"WaveAcoustics.compute_JH_upper!"},{"category":"method","location":"api/#WaveAcoustics.compute_JH_upper!-Union{Tuple{I}, Tuple{T}, Tuple{LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}}} where {T, I}","page":"API","text":"compute_JH_upper!(JH_upper, Q, JG)\n\nCompute in-place\n\nJH_upper = Q + JG.\n\nwhere JG = τα(tₙ₋₁/₂)⋅JG(X). Assumes JH_upper and Q share the same sparsity pattern, and that JG occupies the leading nnz(JG) entries of that pattern.\n\n\n\n\n\n","title":"WaveAcoustics.compute_JH_upper!"},{"category":"method","location":"api/#WaveAcoustics.compute_L!-Union{Tuple{I}, Tuple{T}, Tuple{Vector{T}, WaveAcoustics.State{T}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, Vector{T}, Vector{T}, T, T, T, T, Vector{T}, Vector{T}, Vector{T}}} where {T, I}","page":"API","text":"compute_L!(\n    L, state, K_m₁xm₁, _2M_m₁xm₁, M_m₂xm₂, τFf₁, τFf₂, \n    τα, τα_q₅, _2q₁, τq₃, \n    vec_m₁, vec_m₂_1, vec_m₂_2)\n\nCompute in-place\n\nL = 2M_m₁xm₁⋅vⁿ⁻¹ - τα⋅K_m₁xm₁⋅dⁿ⁻¹ + τFf₁ + τα_q₅⋅[M_m₂xm₂⋅(2q₁⋅rⁿ⁻¹-τq₃⋅zⁿ⁻¹) + τFf₂; 0_(m₁-m₂)]\n\nwhere τα = τ⋅α(tₙ₋₁/₂), τα_q₅ = τ⋅α(tₙ₋₁/₂)/q₅, τFf₁ = τ⋅F(f₁(tₙ₋₁/₂)), and τFf₂ = τ⋅F(f₂(tₙ₋₁/₂)).\n\n\n\n\n\n","title":"WaveAcoustics.compute_L!"},{"category":"method","location":"api/#WaveAcoustics.compute_L!-Union{Tuple{I}, Tuple{T}, Tuple{Vector{T}, WaveAcoustics.State{T}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, Vector{T}, Vector{T}, Vector{T}, T, T, T, T, Vector{T}, Vector{T}, Vector{T}}} where {T, I}","page":"API","text":"compute_L!(\n    L, _2M_m₁xm₁, M_m₂xm₂, K_m₁xm₁, τFdᵃⁿ, τFf₁, τFf₂, \n    τα, τα_q₅, _2q₁, τq₃,\n    vec_m₁, vec_m₂_1, vec_m₂_2)\n\nCompute in-place\n\nL = 2M_m₁xm₁⋅vⁿ⁻¹ - τα⋅K_m₁xm₁⋅dⁿ⁻¹ - τFdᵃⁿ  + τFf₁ + τα_q₅⋅[M_m₂xm₂⋅(2q₁⋅rⁿ⁻¹-τq₃⋅zⁿ⁻¹) + τFf₂; 0_(m₁-m₂)]\n\nwhere τα = τ⋅α(tₙ₋₁/₂), τα_q₅ = τ⋅α(tₙ₋₁/₂)/q₅, τFdᵃⁿ = τF(dᵃⁿ), τFf₁ = τ⋅F(f₁(tₙ₋₁/₂)), and τFf₂ = τ⋅F(f₂(tₙ₋₁/₂)).\n\n\n\n\n\n","title":"WaveAcoustics.compute_L!"},{"category":"method","location":"api/#WaveAcoustics.compute_L!-Union{Tuple{I}, Tuple{T}, Tuple{Vector{T}, WaveAcoustics.State{T}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, Vector{T}, Vector{T}, Vector{T}, Vector{T}, T, T, T, T, Vector{T}, Vector{T}, Vector{T}}} where {T, I}","page":"API","text":"compute_L!(\n    L, _2M_m₁xm₁, M_m₂xm₂, K_m₁xm₁, ταGvᵃⁿ, τFdᵃⁿ, τFf₁, τFf₂, \n    τα, τα_q₅, _2q₁, τq₃,\n    vec_m₁, vec_m₂_1, vec_m₂_2)\n\nCompute in-place\n\nL = 2M_m₁xm₁⋅vⁿ⁻¹ - τα⋅K_m₁xm₁⋅dⁿ⁻¹ - ταGvᵃⁿ - τFdᵃⁿ  + τFf₁ + τα_q₅⋅[M_m₂xm₂⋅(2q₁⋅rⁿ⁻¹-τq₃⋅zⁿ⁻¹) + τFf₂; 0_(m₁-m₂)]\n\nwhere τα = τ⋅α(tₙ₋₁/₂), τα_q₅ = τ⋅α(tₙ₋₁/₂)/q₅, ταGvᵃⁿ = τ⋅α(tₙ₋₁/₂)⋅G(vᵃⁿ),  τFdᵃⁿ = τ⋅F(dᵃⁿ), τFf₁ = τ⋅F(f₁(tₙ₋₁/₂)), and τFf₂ = τ⋅F(f₂(tₙ₋₁/₂)).\n\n\n\n\n\n","title":"WaveAcoustics.compute_L!"},{"category":"method","location":"api/#WaveAcoustics.compute_Q!-Union{Tuple{I}, Tuple{T}, Tuple{LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, T, T}} where {T, I}","page":"API","text":"compute_Q!(Q, K_m₁xm₁, _2M_m₁xm₁, M_m₂xm₂, cst₁, cst₂)\n\nCompute in-place\n\nQ = cst₁*K_m₁xm₁ + _2M_m₁xm₁ + cst₂*[M_m₂xm₂ 0_m₂x(m₁-m₂); 0_(m₁-m₂)xm₂ 0_m₂xm₂]\n\nwhere cst₁ = τ²⋅α(tₙ₋₁/₂)/2 and cst₂ = τ²⋅q₄⋅α(tₙ₋₁/₂)/q₅\n\n\n\n\n\n","title":"WaveAcoustics.compute_Q!"},{"category":"method","location":"api/#WaveAcoustics.compute_minusH!-NTuple{6, Any}","page":"API","text":"compute_minusH!(minusH, v̂ⁿ, Q, G, F, L)\n\nCompute in-place -H(X) where\n\n-H = - Qv̂ⁿ - ταG(v̂ⁿ) - τF(d̂ⁿ) + L\n\n\n\n\n\n","title":"WaveAcoustics.compute_minusH!"},{"category":"method","location":"api/#WaveAcoustics.compute_minusH!-Union{Tuple{I}, Tuple{T}, Tuple{Vector{T}, Vector{T}, LinearAlgebra.Symmetric{T, SparseArrays.SparseMatrixCSC{T, I}}, Vector{T}, Vector{T}}} where {T, I}","page":"API","text":"compute_minusH!(minusH, X, Q, G, L)\n\nCompute in-place\n\n-H(X) = - QX - G + L\n\nwhere G = τα(tₙ₋₁/₂)⋅G(X).\n\n\n\n\n\n","title":"WaveAcoustics.compute_minusH!"},{"category":"method","location":"api/#WaveAcoustics.compute_rates!-Tuple{AbstractArray, AbstractArray, Vector}","page":"API","text":"compute_rates!(rates, errors, δ)\n\nFills rates in-place: rates[i,j] = log(e[i-1,j]/e[i,j]) / log(δ[i-1]/δ[i]) for i ≥ 2. Row 1 is left as zero (no previous level available).\n\n\n\n\n\n","title":"WaveAcoustics.compute_rates!"},{"category":"method","location":"api/#WaveAcoustics.compute_r̂ⁿ!-NTuple{9, Any}","page":"API","text":"compute_r̂ⁿ!(r̂ⁿ, v̂ⁿ, rⁿ⁻¹, zⁿ⁻¹, sol, cst1, cst2, cst3, cst4)\n\nCompute in-place \n\nr̂ⁿ = cst1⋅v̂ⁿ[1:m₂] + cst2⋅rⁿ⁻¹ + cst3⋅zⁿ⁻¹ + cst4⋅sol\n\nwhere cst1 = -τ⋅q₄/q₅, cst2 = 2⋅q₁/q₅, cst3 = -τ⋅q₃/q₅, cst4 = 1/q₅, and sol = inv(M_m₂xm₂)⋅τFf₂\n\n\n\n\n\n","title":"WaveAcoustics.compute_r̂ⁿ!"},{"category":"method","location":"api/#WaveAcoustics.solve_nonlinear_system!-Union{Tuple{T}, Tuple{WaveAcoustics.Scheme1Cache{T}, WaveAcoustics.State{T}, Tuple{T, T}, FEM.DOFMap, FEM.DOFMap, WaveAcoustics.QuadratureSetup, PDEInputData, Vararg{T, 4}}} where T","page":"API","text":"solve_nonlinear_system!(\n    cache, state, element_side_lengths,\n    dof_map_m₁, dof_map_m₂, quad, input_data,\n    τ, τ_2, τ²_2, τα;\n    abstol, reltol, maxiter)\n\nSolve the nonlinear system\n\nH(v̂ⁿ) = Q v̂ⁿ + τα G^m₁(v̂ⁿ) + τ F^m₁(d̂ⁿ) - L = 0\n\nvia Newton's method, updating cache.v̂ⁿ in-place.  cache.v̂ⁿ is warm-started from vⁿ⁻¹ and d̂ⁿ = (τ2)v̂ⁿ + dⁿ¹.\n\nConvergence is declared when either of the following holds at iteration k:\n\nResidual criterion: maxH(Xᵏ)  abstol\nStep criterion: maxXᵏ¹-Xᵏ  abstol + reltol  maxXᵏ\n\n\n\n\n\n","title":"WaveAcoustics.solve_nonlinear_system!"},{"category":"method","location":"api/#WaveAcoustics.solve_nonlinear_system!-Union{Tuple{T}, Tuple{WaveAcoustics.Scheme2Cache{T}, WaveAcoustics.State{T}, Tuple{T, T}, FEM.DOFMap, WaveAcoustics.QuadratureSetup, PDEInputData, T}} where T","page":"API","text":"solve_nonlinear_system!(\n    cache, state, element_side_lengths,\n    dof_map_m₂, quad, input_data,\n    τα;\n    abstol, reltol, maxiter)\n\nSolve the nonlinear system\n\nH(X) = QX + ταG(X) - L₁ = 0\n\nfor X = v̂ⁿ via Newton's method, updating cache.v̂ⁿ in-place.  cache.v̂ⁿ is warm-started from vⁿ⁻¹.\n\nConvergence is declared when either of the following holds at iteration k:\n\nResidual criterion: maxH(Xᵏ¹)  abstol\nStep criterion: maxXᵏ-Xᵏ¹  abstol + reltol  maxXᵏ¹\n\n\n\n\n\n","title":"WaveAcoustics.solve_nonlinear_system!"},{"category":"function","location":"api/#WaveAcoustics.solve_ode","page":"API","text":"solve_ode(cache, tspan, state, matrices, nel_per_dim, element_side_lengths,\n          dof_map_m₁, dof_map_m₂, quad, input_data, callback)\n\nAdvance state over tspan using the time integration scheme solver. Dispatches on cache to the appropriate implementation.\n\nArguments\n\ncache: pre-allocated workspace; see build_cache.\ntspan::StepRangeLen{T}: time grid defined as t₀:τ:t_end.\nstate::State: solution state; modified in-place at each time step.\nmatrices::SystemMatrices: global FEM matrices.\nnel_per_dim::NTuple{2, I}: Number of elements along each spatial dimension\nelement_side_lengths::NTuple{2, T}: Element side lengths (Δx, Δy)\ndof_map_m₁::DOFMap: DOF map for the m₁-space\ndof_map_m₂::DOFMap: DOF map for the m₂-space\nquad::QuadratureSetup: precomputed quadrature data\ninput_data::PDEInputData: input data container for the PDE system\ncallback::AbstractCallback: invoked after each time step\n\n\n\n\n\n","title":"WaveAcoustics.solve_ode"},{"category":"method","location":"api/#WaveAcoustics.solve_v̂ⁿ-Union{Tuple{I}, Tuple{T}, Tuple{WaveAcoustics.Scheme2Cache{T}, WaveAcoustics.State{T}, WaveAcoustics.SystemMatrices{T}, Tuple{I, I}, Tuple{T, T}, FEM.DOFMap, FEM.DOFMap, WaveAcoustics.QuadratureSetup, PDEInputData, Vararg{T, 11}}} where {T, I}","page":"API","text":"solve_v̂ⁿ(\n    cache, state, matrices, nel_per_dim, element_side_lengths,\n    dof_map_m₁, dof_map_m₂, quad, input_data, \n    τ, τα, τα_q₅, _2q₁, τq₃, τ²α_2, τ²q₄α_q₅, Δx, τ_jac_1d, τ_jac_2d, t_half)\n\nSequentially:\n\nComputes Q₁(n)\nComputes τ⋅F(f₁(tₙ₋₁/₂))\nComputes τ⋅F(f₂(tₙ₋₁/₂))\nComputes τ⋅F(dᵃⁿ)\nComputes L(n,dᵃⁿ)\nSolves the nonlinear system Q⋅v̂ⁿ + τα⋅G(v̂ⁿ) - L = 0\n\nWARNING: Assumes that cache.dᵃⁿ has already been populated.\n\n\n\n\n\n","title":"WaveAcoustics.solve_v̂ⁿ"},{"category":"method","location":"api/#WaveAcoustics.solve_v̂ⁿ-Union{Tuple{I}, Tuple{T}, Tuple{WaveAcoustics.Scheme3Cache{T}, WaveAcoustics.State{T}, WaveAcoustics.SystemMatrices{T}, Tuple{I, I}, Tuple{T, T}, FEM.DOFMap, FEM.DOFMap, WaveAcoustics.QuadratureSetup, PDEInputData, Vararg{T, 11}}} where {T, I}","page":"API","text":"solve_v̂ⁿ(\n    cache, state, matrices, nel_per_dim, element_side_lengths,\n    dof_map_m₁, dof_map_m₂, quad, input_data, \n    τ, τα, τα_q₅, _2q₁, τq₃, τ²α_2, τ²q₄α_q₅, Δx, τ_jac_1d, τ_jac_2d, t_half)\n\nSequentially:\n\nComputes Q(n)\nComputes τ⋅F(f₁(tₙ₋₁/₂))\nComputes τ⋅F(f₂(tₙ₋₁/₂))\nComputes τα⋅G(vᵃⁿ)\nComputes τ⋅F(dᵃⁿ)\nComputes L(n,vᵃⁿ,dᵃⁿ)\nSolves the linear system Q⋅v̂ⁿ = L\n\nWARNING: Assumes that cache.vᵃⁿ and cache.dᵃⁿ have already been populated.\n\n\n\n\n\n","title":"WaveAcoustics.solve_v̂ⁿ"},{"category":"method","location":"api/#WaveAcoustics.write_result-Tuple{String, ConvergenceResults}","page":"API","text":"write_result(filename, result)\n\nAppends result to filename in plain-text format.\n\n\n\n\n\n","title":"WaveAcoustics.write_result"},{"category":"section","location":"schemes/scheme1/#Scheme-1","page":"Scheme 1","text":"The numerical scheme present is based on the Crank-Nicolson Galerkin method, which consists of finding U^n V^n in mathcalV_m_1, and Z^n R^n in mathcalV_m_2 such that\n\nbeginalign*\n big(varphibarpartialV^nbig)\n+ alpha^n-frac12Big\n    big(nablavarphinablawidehatU^nbig)\n  - big(varphiwidehatR^n)_Gamma_1\n  + big(varphig(widehatV^n)big)_Gamma_1Big\n+ big(varphif(widehatU^n)big) \n= big(varphif_1^n-frac12big)\nquadforallvarphiin mathcalV_m_1\n5pt\n big(phiq_1barpartialR^n\n+ q_2widehatR^n\n+ q_3widehatZ^n\n+ q_4widehatV^nbig)_Gamma_1\n= big(phif_2^n-frac12big)_Gamma_1\nquadforallphiin mathcalV_m_2\n5pt\n \nbarpartialU^n = widehatV^nquad \nbarpartialZ^n = widehatR^n\nendalign*\n\nwith U^0 V^0 in mathcalV_m_1, and Z^0 R^0 in mathcalV_m_2 given as approximations of the initial solutions u_0,  v_0,  z_0, and r_0. We define these approximations by solving the following projections problems: find  U^0 V^0 in mathcalV_m_1, and Z^0R^0 in mathcalV_m_2 such that\n\nbeginalign*\n big(nablavarphinabla U^0big) \n= big(nablavarphinabla u_0big) \nforallvarphiin mathcalV_m_1\n\n big(nablavarphinabla V^0big) \n= big(nablavarphinabla v_0big)\nforallvarphiin mathcalV_m_1\n\n big(phiZ^0big)_Gamma_1 \n= big(phiz_0big)_Gamma_1\nforallphiin mathcalV_m_2\n\n big(phiR^0big)_Gamma_1 \n= big(phir_0big)_Gamma_1\nforallphiin mathcalV_m_2\nendalign*\n\ndetails: Notation\nmathcalV_m_1 subset H_Gamma_0^1(Omega): Subspace of dimension m_1 with basis varphi_j_j=1^m_1.\nmathcalV_m_2 = mathcalV_m_1_Gamma_1: Subspace of dimension m_2 with basis phi_j_j=1^m_2, where the basis functions of mathcalV_m_1 are indexed so that    phi_j = varphi_j_Gamma_1 quad j = 1 dots m_2For a sufficiently regular time-dependent function w, tau the time step, and t_n = ntau:\n    w^n = w(t_n) qquad\n    barpartialw^n = fracw^n - w^n-1tau approx w^prime(t_n-frac12) qquad\n    widehatw^n = fracw^n + w^n-12 approx w(t_n-frac12)\nwhere t_n-frac12 denotes the midpoint of t_n-1 t_n.","title":"Scheme 1"},{"category":"section","location":"schemes/scheme1/#Matrix-Formulation","page":"Scheme 1","text":"Representing the approximate solutions in terms of the basis functions,\n\nU^n      = sum_j=1^m_1 d_j^nvarphi_j\nV^n      = sum_j=1^m_1 v_j^nvarphi_j\nZ^n      = sum_j=1^m_2 z_j^nphi_j\nR^n      = sum_j=1^m_2 r_j^nphi_j\n\nand choosing test functions varphi=varphi_i for i = 1 ldots m_1, and phi=phi_i for i = 1 ldots m_2, we obtain the system\n\nbeginalign*\n M^m_1times m_1barpartialv^n\n+ alpha^n-frac12Big  \n    K^m_1times m_1widehatd^n\n  - M^m_1times m_2widehatr^n\n  + G^m_1(widehatv^n)Big\n+ F^m_1(widehatd^n)\n= mathcalF^m_1(f_1^n-frac12)\n3pt\n M^m_2times m_2big\n  q_1barpartialr^n\n+ q_2widehatr^n\n+ q_3widehatz^nbig\n+ q_4M^m_2times m_1widehatv^n\n= mathcalF^m_2(f_2^n-frac12)\n5pt\n barpartiald^n = widehatv^nquad\nbarpartialz^n = widehatr^n\nendalign*\n\nwith initial solution given by\n\nK^m_1times m_1 d^0 = kappa^m_1(u_0)quad\nK^m_1times m_1 v^0 = kappa^m_1(v_0)quad\nM^m_2times m_2 z^0 = mathcalF^m_2(z_0)quad\nM^m_2times m_2 r^0 = mathcalF^m_2(r_0)\n\ndetails: Matrix and vector definitions\nbeginaligned\n\nM^m_1times m_1_ij = (varphi_ivarphi_j)quad \nM^m_1times m_2_ij = (varphi_iphi_j)_Gamma_1quad \nM^m_2times m_1_ij = (phi_ivarphi_j)_Gamma_1quad \nM^m_2times m_2_ij = (phi_iphi_j)_Gamma_1\n5pt\n\nmathcalF_i^m_1(w) = big(varphi_iwbig)quad\nmathcalF_i^m_2(w) = big(phi_iwbig)_Gamma_1quad\nkappa^m_1(w) = big(nablavarphi_inabla wbig)\n5pt\n\nG^m_1_i(widehatv^n) \n= big(varphi_ig(widehatV^n)big)_Gamma_1\nequivint_Gamma_1varphi_i(x)gBig(xsum_ell=1^m_1widehatv_ell^nvarphi_ell(x)Big)dGamma\n5pt\n\nF_i^m_1(widehatd^n) \n= big(varphi_if(widehatU^n)big)\nequivint_Omegavarphi_i(x)fBig(sum_ell=1^m_1widehatd_ell^nvarphi_ell(x)Big)dx\nendalignednote: Beware!\nAlthough q_1, q_2, and q_3 are functions in the original model, we treat them as constants from this point on. This is a deliberate simplification adopted to reduce the complexity of the numerical implementation.\nThe index convention imposed on the basis functions of mathcalV_m_1 and mathcalV_m_2, namely\n      phi_j = varphi_j_Gamma_1 quad j = 1 dots m_2\nallows us to rewrite the matrices M^m_1times m_2 and M^m_2times m_1 as\n      M^m_1times m_2 = beginbmatrix M^m_2times m_2  0^(m_1-m_2)times m_2 endbmatrix\n      quadtextandquad\n      M^m_2times m_1 = beginbmatrix M^m_2times m_2  0^m_2times(m_1-m_2) endbmatrix\nFurthermore, the nonlinear term G^m_1(widehatv^n) can be rewritten as\nG^m_1(widehatv^n) \n= beginbmatrix G^m_2(widehatv_1m_2^n) 0^(m_1-m_2) endbmatrix\nwith\nG^m_2_i(widehatv_1m_2^n) \n=int_Gamma_1phi_i(x)gBig(xsum_ell=1^m_2widehatv_ell^nphi_ell(x)Big)dGamma","title":"Matrix Formulation"},{"category":"section","location":"schemes/scheme1/#Solving-the-Nonlinear-Algebraic-System","page":"Scheme 1","text":"In what follows, we show that the matrix formulation is equivalent to finding X in mathbbR^m_1 such that H(X) = 0,  which we solve via Newton's method. Starting from the initial guess  X_0 = v^n-1,  the method generates the sequence  X_kappa+1 = X_kappa + S_kappa,  where S_kappa is obtained by solving the linear system\n\nJH(X_kappa) S_kappa = -H(X_kappa)\n\nwith JH(X_kappa) denoting the Jacobian of H evaluated at X_kappa.","title":"Solving the Nonlinear Algebraic System"},{"category":"section","location":"schemes/scheme1/#Formulation-in-Term-of-X\\hat{v}n","page":"Scheme 1","text":"Q(n) hatv^n\n+ taualpha^n-frac12 G^m_1(widehatv^n) + tau F^m_1(fractau2widehatv^n + d^n-1)\n- L_1(n)\n= 0\n\nOnce hatv^n has been determined, we compute hatr^n via\n\nhatr^n\n=\n- fractau q_4q_5hatv_1m_2^n\n+ frac2q_1q_5 r^n-1\n- fractau q_3q_5 z^n-1\n+ fractauq_5 Big(M^m_2times m_2Big)^-1\n  mathcalF^m_2(f_2^n-frac12)\n\nThe remaining quantities d^n, v^n, z^n, and r^n are then recovered by\n\nbeginalign*\n v^n = 2hatv^n - v^n-1\nquad r^n = 2hatr^n - r^n-1\nquad d^n = tauhatv^n + d^n-1\nquad z^n = tauhatr^n + z^n-1\nendalign*\n\ndetails: Details\nTo rewrite the matrix formulation in terms of widehatv^n and widehatr^n, we make use of the following identities:barpartial v^n = frac2tauwidehatv^n - frac2tauv^n-1\nquad\nwidehatd^n = fractau2 widehatv^n + d^n-1\nquad\nbarpartial r^n = frac2tauwidehatr^n - frac2tauz^n-1\nquad\nwidehatz^n = fractau2 widehatr^n + z^n-1Applying these identities into the matrix formulation, we obtain:beginalign*\n M^m_1times m_1 big(frac2tauwidehatv^n-frac2tauv^n-1big)\n+ alpha^n-frac12Big  \n    K^m_1times m_1 big(fractau2widehatv^n+d^n-1big)\n  - M^m_1times m_2widehatr^n\n  + G^m_1(widehatv^n)Big\n+ F^m_1(fractau2widehatv^n + d^n-1)\n= mathcalF^m_1(f_1^n-frac12)\n10pt\n M^m_2times m_2big\n  q_1big(frac2tauwidehatr^n-frac2taur^n-1big)\n+ q_2widehatr^n\n+ q_3big(fractau2widehatr^n+z^n-1big)big\n+ q_4M^m_2times m_1widehatv^n\n= mathcalF^m_2(f_2^n-frac12)\nendalign*Isolating widehatr^n in the second equation:(2q_1+tau q_2+fractau^22q_3)M^m_2times m_2 widehatr^n\n=\n- tau q_4M^m_2times m_2 widehatv_1m_2^n\n+ M^m_2times m_2big(2q_1r^n-1 - tau q_3z^n-1big)\n+ tau mathcalF^m_2(f_2^n-frac12)Denoting q_5 = 2q_1+tau q_2+fractau^22q_3 and using the result above in the first equation, we obtain:beginalign*\n M^m_1times m_1 big(frac2tauwidehatv^n-frac2tauv^n-1big)\n+ alpha^n-frac12Big  \n    K^m_1times m_1 big(fractau2widehatv^n+d^n-1big)\n  + G^m_1(widehatv^n)Big\n+ F^m_1(fractau2widehatv^n + d^n-1)\n10pt\nqquad\n+ fracalpha^n-frac12q_5\nbeginbmatrix\n  tau q_4M^m_2times m_2 widehatv_1m_2^n\n  - M^m_2times m_2big( 2q_1r^n-1 - tau q_3z^n-1 big)\n  - tau mathcalF^m_2(f_2^n-frac12)\n  5pt\n  0^(m_1-m_2)\nendbmatrix\n= mathcalF^m_1(f_1^n-frac12)\nendalign*Isolating widehatv^n:beginalign*\n\nBig(\n    2M^m_1times m_1\n    + fractau^22alpha^n-frac12 K^m_1times m_1\n    + fractau^2q_4q_5alpha^n-frac12\n      beginbmatrix\n      M^m_2times m_2        0^m_2times(m_1-m_2)5pt\n      0^(m_1-m_2)times m_2  0^(m_1-m_2)times(m_1-m_2)\n      endbmatrix\nBig) widehatv^n\n10pt\nqquad\n+ taualpha^n-frac12 G^m_1(widehatv^n) \n+ tau F^m_1(fractau2widehatv^n + d^n-1)\n- L(n) = 0\nendalign*note: Beware!\nbeginalign*\n\nbarpartial v^n \n= fracv^n-v^n-1tau\n= frac2fracv^n+v^n-12-v^n-1-v^n-1tau\n= frac2widehatv^n-2v^n-1tau\nquadRightarrowquad\nbarpartial v^n = frac2tauwidehatv^n - frac2tauv^n-1\n10pt\n\nbarpartial d^n = widehatv^n\nRightarrow\nfracd^n-d^n-1tau = widehatv^n\nRightarrow\nd^n = tau widehatv^n + d^n-1\nRightarrow\nfracd^n+d^n-12 = fractau2 widehatv^n + d^n-1\nquadRightarrowquad\nwidehatd^n = fractau2 widehatv^n + d^n-1\nendalign*\n\ndetails: Matrix and vector definitions\nbeginalign*\nQ =\n2M^m_1times m_1 \n+ fractau^22alpha^n-frac12K^m_1times m_1\n+ fractau^2q_4q_5alpha^n-frac12\nbeginbmatrix\nM^m_2times m_2        0^m_2times(m_1-m_2)\n5pt\n0^(m_1-m_2)times m_2  0^(m_1-m_2)times(m_1-m_2)\nendbmatrix\n30pt\nL =\n2M^m_1times m_1v^n-1\n- tau alpha^n-frac12K^m_1times m_1 d^n-1\n+ tau mathcalF^m_1(f_1^n-frac12)\n+ fractauq_5alpha^n-frac12\nbeginbmatrix\n  M^m_2times m_2big( 2q_1r^n-1 - tau q_3z^n-1 big)\n  + tau mathcalF^m_2(f_2^n-frac12)\n  5pt\n  0^(m_1-m_2)\nendbmatrix\nendalign*where q_5 = 2q_1+tau q_2+fractau^22q_3.\n\ndetails:  Jacobian matrix calculation\nJH(X) \n= Q\n+ taualpha^n-frac12 JGbig(Xbig)\n+ fractau^22 JFbig(fractau2X+d^n-1big)note: Beware!\nJG^m_1times m_1(X) =\nbeginbmatrixdisplaystyle\nJG^m_2times m_2(X_1m_2)  0^m_2times(m_1-m_2)\n10pt\n0^(m_1-m_2)times m_2        0^(m_1-m_2)times(m_1-m_2)\nendbmatrixJG^m_2times m_2_ij(X_1m_2)\n= int_Gamma_1phi_i(x)phi_j(x)fracpartial gpartial sbig(xsum_ell=1^m_2X_ellphi_ell(x)big)dGammaJF_ij(fractau2X+d^n-1) = \nint_Omegavarphi_i(x)varphi_j(x)f^primeBig(sum_ell=1^m_1\nbigfractau2X_ell+d_ell^n-1big\nvarphi_ell(x)Big)dx","title":"Formulation in Term of X=hatv^n"},{"category":"section","location":"schemes/scheme3/#Scheme-3","page":"Scheme 3","text":"The following scheme is defined using the linearized Crank-Nicolson Galerkin method, which consists of finding U^n V^n in mathcalV_m_1 and Z^n R^n in mathcalV_m_2 such that\n\nbeginalign*\nbeginaligned\n big(varphibarpartialV^nbig)\n+ alpha^n-frac12Big\n    big(nablavarphinablawidehatU^nbig)\n  - big(varphiwidehatR^n)_Gamma_1\n  + big(varphig(V^ast n)big)_Gamma_1Big\n+ big(varphif(U^ast n)big) \n= big(varphif_1^n-frac12big)\nquadforallvarphiin mathcalV_m_1\n\n big(phiq_1barpartialR^n\n+ q_2widehatR^n\n+ q_3widehatZ^n\n+ q_4widehatV^nbig)_Gamma_1\n= big(phif_2^n-frac12big)_Gamma_1\nquadforallphiin mathcalV_m_2\n\n \nbarpartialU^n = widehatV^nquad \nbarpartialZ^n = widehatR^n\nendaligned\nendalign*\n\nfor n = text1012ldots, with U^0 V^0 in mathcalV_m_1 and Z^0 R^0 in mathcalV_m_2 given as approximations of the initial conditions u_0 v_0 z_0, and r_0, defined in the same way as in Scheme 1.","title":"Scheme 3"},{"category":"section","location":"schemes/scheme3/#Matrix-Formulation","page":"Scheme 3","text":"beginalign*\nbeginaligned\n M^m_1times m_1barpartialv^n\n+ alpha^n-frac12Big  \n    K^m_1times m_1widehatd^n\n  - M^m_1times m_2widehatr^n\n  + G^m_1(v^ast n)Big\n+ F^m_1(d^ast n)\n= mathcalF^m_1(f_1^n-frac12)\n\n M^m_2times m_2big\n  q_1barpartialr^n\n+ q_2widehatr^n\n+ q_3widehatz^n\n+ q_4M^m_2times m_1widehatv^n\n= mathcalF^m_2(f_2^n-frac12)\n\n barpartiald^n = widehatv^nquad\nbarpartialz^n = widehatr^n\nendaligned\nendalign*","title":"Matrix Formulation"},{"category":"section","location":"schemes/scheme3/#Solving-the-Algebraic-Systems","page":"Scheme 3","text":"Q(n) widehatv^n \n= L(nv^*nd^*n)\n\nOnce hatv^n has been determined, we compute hatr^n via\n\nhatr^n\n=\n- fractau q_4q_5hatv_1m_2^n\n+ frac2q_1q_5 r^n-1\n- fractau q_3q_5 z^n-1\n+ fractauq_5 Big(M^m_2times m_2Big)^-1\n  mathcalF^m_2(f_2^n-frac12)\n\nand the remaining quantities d^n, v^n, z^n, and r^n by\n\nbeginalign*\n v^n = 2hatv^n - v^n-1\nquad r^n = 2hatr^n - r^n-1\nquad d^n = tauhatv^n + d^n-1\nquad z^n = tauhatr^n + z^n-1\nendalign*\n\ndetails: Matrix and vector definitions\nbeginalign*\nQ =  \n2M^m_1times m_1 \n+ fractau^22alpha^n-frac12K^m_1times m_1\n+ fractau^2q_4q_5alpha^n-frac12\nbeginbmatrix\nM^m_2times m_2        0^m_2times(m_1-m_2)5pt\n0^(m_1-m_2)times m_2  0^(m_1-m_2)times(m_1-m_2)\nendbmatrix\n10pt\nL =\n-taualpha^n-frac12 G^m_1(v^ast n)  \n- tau F^m_1(d^ast n)\n+ 2M^m_1times m_1v^n-1\n- tau alpha^n-frac12K^m_1times m_1 d^n-1\n+ tau mathcalF^m_1(f_1^n-frac12)\n+ fractauq_5alpha^n-frac12\nbeginbmatrix\n  M^m_2times m_2big( 2q_1r^n-1 - tau q_3z^n-1 big)\n  + tau mathcalF^m_2(f_2^n-frac12)\n  5pt\n  0^(m_1-m_2)\nendbmatrix\nendalign*","title":"Solving the Algebraic Systems"},{"category":"section","location":"model/#Strong-Formulation","page":"Model","text":"We seek functions u and z satisfying the following system of equations:\n\nbeginalignlabelpdemdl\nbeginaligned\n u^primeprime(xt) \n- alpha(t)Delta u(xt) \n+ fbig(u(xt)big) \n= f_1(xt)\nquad(xt)inOmegatimes(0+infty)\n5pt\n q_1 z^primeprime(xt)\n+ q_2 z^prime(xt)\n+ q_3 z(xt)\n+ q_4 u^prime(xt)\n= f_2(xt)\nquad(xt)inGamma_1times(0+infty)\n5pt\n fracpartial upartialnu(xt)\n= z^prime(xt)\n- gbig(xu^prime(xt)big)\nquad(xt)inGamma_1times(0+infty)\n5pt\n u(xt) = 0quad (xt)inGamma_0times(0+infty)\nendaligned\nendalign\n\nwith initial conditions\n\nbeginalignlabelpdemdlinitial_condition\nbeginaligned\n u(x0) = u_0(x)quad u^prime(x0)=v_0(x)quad xinOmega\n\n z(x0) = z_0(x)quad\n  z^prime(x0) = r_0(x) equiv fracpartial u_0partialnu(x) + gbig(xv_0(x)big)quad xinGamma_1\nendaligned\nendalign\n\nwhere Omega is a bounded open subset of mathbbR^n, ngeq 2, with smooth boundary Gamma=Gamma_0cupGamma_1 and disjoint Gamma_0, Gamma_1.\n\nExistence and uniqueness results for particular cases of \\eqref{pde:mdl}–\\eqref{pde:mdl:initial_condition} can be found in:\n\nAlcântara et al. (2025). Numerical analysis for nonlinear wave equations with boundary conditions: Dirichlet, Acoustics and Impenetrability. Applied Mathematics and Computation. https://doi.org/10.1016/j.amc.2024.129009","title":"Strong Formulation"},{"category":"section","location":"model/#Weak-Formulation","page":"Model","text":"We seek functions u(t)in H_Gamma_0^1(Omega) and z(t)in L^2(Gamma_1) such that\n\nbeginalign\nlabelpdevariational_form\nbeginaligned\n big(varphiu^primeprime(t)big)\n+ alpha(t)Big\n    big(nablavarphinabla u(t)big)\n  - big(varphiz^prime(t))_Gamma_1\n  + big(varphigbig(u^prime(t)big)big)_Gamma_1Big\n+ big(varphifbig(u(t)big)big) \n= big(varphif_1(t)big)\nquadforallvarphiin H_Gamma_0^1(Omega)\n\n big(phiq_1z^primeprime(t)\n+ q_2z^prime(t)\n+ q_3z(t)\n+ q_4u^prime(t)big)_Gamma_1\n= big(phif_2(t)big)_Gamma_1\nquadforallphiin L^2(Gamma_1)\nendaligned\nendalign\n\nwith  u(0)=u_0,  u^prime(0)=v_0,  z(0)=z_0, and  z^prime(0) = r_0 equiv fracpartial u_0partialnu + g(v_0). \n\nBy introducing the auxiliary variables v(t)=u^prime(t) and r(t)=z^prime(t), we obtain the equivalent first-order system: find functions u(t)v(t)in H_Gamma_0^1(Omega) and z(t)r(t)in L^2(Gamma_1) such that\n\nbeginalign\nlabelpdevariational_form_opt2\nbeginaligned\n big(varphiv^prime(t)big)\n+ alpha(t)Big\n    big(nablavarphinabla u(t)big)\n  - big(varphir(t)big)_Gamma_1\n  + big(varphigbig(v(t)big)big)_Gamma_1Big\n+ big(varphifbig(u(t)big)big) \n= big(varphif_1(t)big)\nquadforallvarphiin H_Gamma_0^1(Omega)\n\n big(phiq_1r^prime(t)\n+ q_2r(t)\n+ q_3z(t)\n+ q_4v(t)big)_Gamma_1\n= big(phif_2(t)big)_Gamma_1\nquadforallphiin L^2(Gamma_1)\n\n u^prime(t)=v(t)quad z^prime(t)=r(t)\nendaligned\nendalign\n\nwith initial conditions u(0)=u_0,  v(0)=v_0,  z(0)=z_0, and  r(0) = r_0 equiv fracpartial u_0partialnu + g(v_0).\n\ndetails: Notation: Functional spaces, inner products, and norms\nWe consider  H_Gamma_0^1(Omega) =  v in H^1(Omega) v_Gamma_0 = 0   and the inner products and norms in L^2(Omega) and L^2(Gamma_1) by(cdot cdot)quad\n(cdot cdot)_Gamma_1quad\ncdotquad\ncdot_Gamma_1","title":"Weak Formulation"},{"category":"section","location":"schemes/scheme2/#Scheme-2","page":"Scheme 2","text":"The following fully discrete scheme combines the Crank-Nicolson Galerkin method with selective linearization of nonlinear terms.  It consists of finding U^n V^n in mathcalV_m_1, and Z^n R^n in mathcalV_m_2 such that\n\nbeginalign*\n big(varphibarpartialV^nbig)\n+ alpha^n-frac12Big\n    big(nablavarphinablawidehatU^nbig)\n  - big(varphiwidehatR^n)_Gamma_1\n  + big(varphig(widehatV^n)big)_Gamma_1Big\n+ big(varphif(U^ast n)big) \n= big(varphif_1^n-frac12big)\nquadforallvarphiin mathcalV_m_1\n5pt\n big(phiq_1barpartialR^n\n+ q_2widehatR^n\n+ q_3widehatZ^n\n+ q_4widehatV^nbig)_Gamma_1\n= big(phif_2^n-frac12big)_Gamma_1\nquadforallphiin mathcalV_m_2\n5pt\n \nbarpartialU^n = widehatV^nquad \nbarpartialZ^n = widehatR^n\nendalign*\n\nfor n = text1012ldots, with U^0 V^0 in mathcalV_m_1, and Z^0 R^0 in mathcalV_m_2 given as approximations of the initial solutions u_0,  v_0,  z_0, and r_0, defined in the same manner as in Scheme 1.\n\ndetails: Notation\nIn addition to the operators  displaystylebarpartialw^n=fracw^n - w^n-1tau and  displaystylewidehatw^n = fracw^n + w^n-12, considerbarpartialw^text10 = fracw^text10 - w^0tauquad\nwidehatw^text10 = fracw^text10 + w^02\nquadtextandquad\nw^*n = \nbegincasesdisplaystyle\nw^0                              textif  n = text10\n10pt displaystyle\nfracw^text10+w^02  textif  n = 1\n10pt displaystyle\nfrac3w^n-1-w^n-22       textif  n geq 2\nendcases","title":"Scheme 2"},{"category":"section","location":"schemes/scheme2/#Matrix-Formulation","page":"Scheme 2","text":"beginalign*\n M^m_1times m_1barpartialv^n\n+ alpha^n-frac12Big  \n    K^m_1times m_1widehatd^n\n  - M^m_1times m_2widehatr^n\n  + G^m_1(widehatv^n)Big\n+ F^m_1(d^ast n)\n= mathcalF^m_1(f_1^n-frac12)\n3pt\n M^m_2times m_2big\n  q_1barpartialr^n\n+ q_2widehatr^n\n+ q_3widehatz^nbig\n+ q_4M^m_2times m_1widehatv^n\n= mathcalF^m_2(f_2^n-frac12)\n5pt\n barpartiald^n = widehatv^nquad\nbarpartialz^n = widehatr^n\nendalign*","title":"Matrix Formulation"},{"category":"section","location":"schemes/scheme2/#Solving-the-Algebraic-Systems","page":"Scheme 2","text":"The matrix formulation can be rewritten as:\n\nbeginalign*\n\nbigQ(n)big^m_1times m_1 widehatv^n\n+ taualpha^n-frac12 G^m_1(widehatv^n) \n- L(nd^ast n) = 0\n10pt\n hatr^n\n=\n- fractau q_4q_5hatv_1m_2^n\n+ frac2q_1q_5 r^n-1\n- fractau q_3q_5 z^n-1\n+ fractauq_5 Big(M^m_2times m_2Big)^-1\n  mathcalF^m_2(f_2^n-frac12)\nendalign*\n\nThe first system is nonlinear in widehatv^n, independent of widehatr^n, and is solved via Newton's method. Once widehatv^n is available, widehatr^n follow explicitly from the second equation.\n\nWith hatv^n and hatr^n determined, the remaining unknowns are updated via\n\nbeginalign*\n v^n = 2hatv^n - v^n-1\nquad r^n = 2hatr^n - r^n-1\nquad d^n = tauhatv^n + d^n-1\nquad z^n = tauhatr^n + z^n-1\nendalign*\n\ndetails: Details\nRewriting the matrix formulation in terms of widehatv^n and widehatr^n, we obtain:beginalign*\n M^m_1times m_1 big(frac2tauwidehatv^n-frac2tauv^n-1big)\n+ alpha^n-frac12Big  \n    K^m_1times m_1 big(fractau2widehatv^n+d^n-1big)\n  - M^m_1times m_2widehatr^n\n  + G^m_1(widehatv^n)Big\n+ F^m_1(d^ast n)\n= mathcalF^m_1(f_1^n-frac12)\n10pt\n M^m_2times m_2big\n  q_1big(frac2tauwidehatr^n-frac2taur^n-1big)\n+ q_2widehatr^n\n+ q_3big(fractau2widehatr^n+z^n-1big)big\n+ q_4M^m_2times m_1widehatv^n\n= mathcalF^m_2(f_2^n-frac12)\nendalign*Isolating widehatr^n in the second equation:(2q_1+tau q_2+fractau^22q_3)M^m_2times m_2 widehatr^n\n=\n- tau q_4M^m_2times m_2 widehatv_1m_2^n\n+ M^m_2times m_2big(2q_1r^n-1 - tau q_3z^n-1big)\n+ tau mathcalF^m_2(f_2^n-frac12)Denoting q_5 = 2q_1+tau q_2+fractau^22q_3 and using the result above in the first equation, we obtain:beginalign*\n M^m_1times m_1 big(frac2tauwidehatv^n-frac2tauv^n-1big)\n+ alpha^n-frac12Big  \n    K^m_1times m_1 big(fractau2widehatv^n+d^n-1big)\n  + G^m_1(widehatv^n)Big\n+ F^m_1(d^ast n)\n10pt\nqquad\n+ fracalpha^n-frac12q_5\nbeginbmatrix\n  tau q_4M^m_2times m_2 widehatv_1m_2^n\n  - M^m_2times m_2big( 2q_1r^n-1 - tau q_3z^n-1 big)\n  - tau mathcalF^m_2(f_2^n-frac12)\n  5pt\n  0^(m_1-m_2)\nendbmatrix\n= mathcalF^m_1(f_1^n-frac12)\n10pt\n hatr^n\n=\n- fractau q_4q_5hatv_1m_2^n\n+ frac2q_1q_5 r^n-1\n- fractau q_3q_5 z^n-1\n+ fractauq_5 Big(M^m_2times m_2Big)^-1\n  mathcalF^m_2(f_2^n-frac12)\nendalign*Isolating widehatv^n:beginalign*\n\nQ(n) widehatv^n\n+ taualpha^n-frac12 G^m_1(widehatv^n) \n- L(nd^ast n) = 0\n10pt\n hatr^n\n=\n- fractau q_4q_5hatv_1m_2^n\n+ frac2q_1q_5 r^n-1\n- fractau q_3q_5 z^n-1\n+ fractauq_5 Big(M^m_2times m_2Big)^-1\n  mathcalF^m_2(f_2^n-frac12)\nendalign*\n\ndetails: Matrix and vector definitions\nbeginalign*\nQ = \n2M^m_1times m_1 \n+ fractau^22alpha^n-frac12K^m_1times m_1\n+ fractau^2q_4q_5alpha^n-frac12\nbeginbmatrix\nM^m_2times m_2        0^m_2times(m_1-m_2)5pt\n0^(m_1-m_2)times m_2  0^(m_1-m_2)times(m_1-m_2)\nendbmatrix\n10pt\nL =\n- tau F^m_1(d^ast n)\n+ 2M^m_1times m_1v^n-1\n- tau alpha^n-frac12K^m_1times m_1 d^n-1\n+ tau mathcalF^m_1(f_1^n-frac12)\n+ fractauq_5alpha^n-frac12\nbeginbmatrix\n  M^m_2times m_2big( 2q_1r^n-1 - tau q_3z^n-1 big)\n  + tau mathcalF^m_2(f_2^n-frac12)\n  5pt\n  0^(m_1-m_2)\nendbmatrix\nendalign*\n\ndetails:  Jacobian matrix calculation\nJH(X) \n= Q + taualpha^n-frac12\n  beginbmatrixdisplaystyle\n  JG^m_2times m_2(X_1m_2)  0^m_2times(m_1-m_2)\n  10pt\n  0^(m_1-m_2)times m_2        0^(m_1-m_2)times(m_1-m_2)\n  endbmatrix whereJG_ij^m_2times m_2(X_1m_2)\n=\nint_Gamma_1 phi_i(x)phi_j(x)\nfracpartial gpartial sBig(xsum_ell=1^m_2X_ellphi_ell(x)Big)dGamma","title":"Solving the Algebraic Systems"},{"category":"section","location":"numerical_results/scheme2/#Scheme-2","page":"Scheme 2","text":"julia> using WaveAcoustics\n\njulia> cases1 = (\n    (fe = Lagrange{1}, id = example1_manufactured(1.76), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example1_manufactured(2.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example1_manufactured(2.58), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example1_manufactured(3.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example1_manufactured(3.51), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example1_manufactured(4.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example1_manufactured(2.4 ), Nx = 2^9, τ = [2.0^-i for i in 2:5])\n    );\n\njulia> results1 = run_cases(Scheme2(), cases1)\n\njulia> cases2 = (\n    (fe = Lagrange{1}, id = example2_manufactured(1.76), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example2_manufactured(2.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example2_manufactured(2.58), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example2_manufactured(3.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example2_manufactured(3.51), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example2_manufactured(4.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example2_manufactured(2.4 ), Nx = 2^9, τ = [2.0^-i for i in 2:5])\n    );\n\njulia> results2 = run_cases(Scheme2(), cases2)\n\njulia> cases3 = (\n    (fe = Lagrange{1}, id = example3_manufactured(1.76), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example3_manufactured(2.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example3_manufactured(2.58), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{2}, id = example3_manufactured(3.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example3_manufactured(3.51), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{3}, id = example3_manufactured(4.4 ), Nx = [2^i for i in 2:6], τ = 2.0^-15),\n    (fe = Lagrange{1}, id = example3_manufactured(2.4 ), Nx = 2^9, τ = [2.0^-i for i in 2:5])\n    );\n\njulia> results3 = run_cases(Scheme2(), cases3)\n\njulia> versioninfo()","title":"Scheme 2"},{"category":"section","location":"#Overview","page":"Home","text":"This package provides numerical solutions for a wave acoustics PDE systems using the finite element method for spatial approximation and finite difference schemes for temporal integration. ","title":"Overview"}]
